	cp A,0x80                                     ; F86848  c9 cf 80
	jr c, .LF8684F                                ; F8684B  67 02
	ld a, 0x00:opc                                   ; F8684D  21 00   ld A,0x00
.LF8684F:
	cp A,0x20                                     ; F8684F  c9 cf 20
	jr c, .LF86856                                ; F86852  67 02
	ld a, 0x1f:opc                                   ; F86854  21 1f   ld A,0x1f
.LF86856:
