	extz WA                                       ; F8685B  d8 12
	add HL,WA                                     ; F8685D  d8 83
	ld A,(XHL)                                    ; F8685F  83 21
	m_bit 0, MD16, UI_RequestBits                         ; F86861  f1 75 20 c8   bit 0,(0x2075)
	jr nz, .LF8686F                               ; F86865  6e 08
