PanelGroupEventLists_Variant2:
	.long PanelGroupEventListPool+0x155                 ; F8B4B2  [0x00] 6 records
	.long PanelGroupEventListPool+0x16E                 ; F8B4B6  [0x01] 1 record
	.long PanelGroupEventListPool+0x173                 ; F8B4BA  [0x02] 4 records
