	bit	0, (0xc6:8)                            ; F8F395  f0 c6 c8
	jr nz, .LF8F39E                               ; F8F398  6e 04
.LF8F39A:
	bit 6,(XHL)                                   ; F8F39A  b3 ce
	jr nz, .LF8F39A                               ; F8F39C  6e fc
