	swi 7                                                ; F9900B  ff
	pop XDE                                              ; F9900C  5a
	pop XHL                                              ; F9900D  5b
	pop XIX                                              ; F9900E  5c
	pop XIZ                                              ; F9900F  5e
	ret                                                  ; F99010  0e
