	minc1_16 hl, 0x01ff                                  ; FA572A  db 38 ff 01
	ld	a, (Seq_BeatTick:8)                                      ; FA572E  c0 93 21
	mx_st_mr8 MXD, ra_IX, ra_HL, r1                      ; FA5731  f3 07 f0 ec 41
	minc1_16 hl, 0x01ff                                  ; FA5736  db 38 ff 01
	ld (xix-4), hl                                       ; FA573A  bc fc 53
