	link XIZ,0x0000                                      ; FBA133  ee 0c 00 00
	push XIX                                             ; FBA137  3c
	ld b, 0x20:opc                                          ; FBA138  22 20
	sub WA,WA                                            ; FBA13A  d8 a0
	sub XIY,XIY                                          ; FBA13C  ed a5
	sub XIX,XIX                                          ; FBA13E  ec a4
