; ---------------------------------------------------------------------
; DiskLoad_CheckSoundRamTag -- is the file just read a WSA sound-RAM file?  A := 0 when the 16 bytes at
;          0x609400 equal Str_SoundRamTag_Wsa ("WSA SOUND RAM S0", all 16 compared), 0xFF at the first byte
;          that differs.
;
; Called from: prom_a DiskLoad_Sound (`calr`) at 0xFE204F, which answers a non-zero A with `ld a,0x10`
;          before any transfer (wsa1/notes/sysex-probes/sysex_signature_checks.py asserts this site).
; Renamed from "NOT NAMED" (round 7 recorded only the string) on 2026-10-03, when 0xFE7000-0xFE706D
;          was re-framed as data.
; ---------------------------------------------------------------------
DiskLoad_CheckSoundRamTag:
	link XIZ,0xfffc                                      ; FE1CE9  ee 0c fc ff
	pushw hl                                             ; FE1CED  2b
	push XIX                                             ; FE1CEE  3c
	ld XIX,0x00609400                                    ; FE1CEF  44 00 94 60 00
	ld h, 0x00:opc                                          ; FE1CF4  26 00
.LFE1CF6:
	ld C,H                                               ; FE1CF6  ce 8b
	extz BC                                              ; FE1CF8  d9 12
	extz XBC                                             ; FE1CFA  e9 12
	ld (xiz-4), xbc                                      ; FE1CFC  be fc 61
	add XBC,Str_SoundRamTag_Wsa                                   ; FE1CFF  e9 c8 27 70 fe 00
	ld L,(XBC)                                           ; FE1D05  81 27
	ld XBC,XIX                                           ; FE1D07  ec 89
	m_add_rm MLD+r6, 0xfc, r1                            ; FE1D09  ae fc 81
	ld A,(XBC)                                           ; FE1D0C  81 21
	cp A,L                                               ; FE1D0E  cf f1
	jr nz, .LFE1D19                                          ; FE1D10  6e 07
	inc 1,H                                              ; FE1D12  ce 61
	cp H,0x10                                            ; FE1D14  ce cf 10
	jr c, .LFE1CF6                                            ; FE1D17  67 dd
.LFE1D19:
	cp H,0x10                                            ; FE1D19  ce cf 10
	jr nz, .LFE1D22                                          ; FE1D1C  6e 04
	sub A,A                                              ; FE1D1E  c9 a1
	jr .LFE1D24                                              ; FE1D20  68 02
.LFE1D22:
	ld a, 0xff:opc                                          ; FE1D22  21 ff
.LFE1D24:
	pop XIX                                              ; FE1D24  5c
	popw hl                                              ; FE1D25  4b
	unlk XIZ                                             ; FE1D26  ee 0d
	ret                                                  ; FE1D28  0e
; ---------------------------------------------------------------------
; Ring_InitTenOfFourteen -- calls the Init entry of TEN of the fourteen ring buffers,
;                           in one run, and returns
;
; Evidence: ten consecutive `call` instructions at 0xFE1D29, 0xFE1D2D,
;           0xFE1D31, 0xFE1D35, 0xFE1D39, 0xFE1D3D, 0xFE1D41, 0xFE1D45,
;           0xFE1D49 and 0xFE1D4D, whose operands are prom_b directory
;           slots T_TimedEventRing_Init, T_SeqBufRing_Init,
;           T_MidiInARing_Init, T_MidiInBRing_Init, T_Ring601432_Init,
;           T_Ring60153C_Init, T_Ring601646_Init, T_Ring601850_Init,
;           T_Ring60195A_Init and T_Ring601C6E_Init -- TEN of the
;           FOURTEEN `T_Ring*_Init` slots in prom_b, and no other call.
;           0xFE1D51 is the `ret`. The four it does NOT call are
;           T_Ring60000C_Init, T_Ring601B64_Init, T_Ring60480A_Init and
;           T_Ring608A0A_Init, and Ring_InitAllFourteen (0xF825D4) calls
;           all fourteen
; Unknown:  why the ninth call is out of address order
;           (T_Ring60195A_Init is reached through slot 0xF41D28, below
;           all the others), why these ten and not the fourteen, and
;           what the buffers carry -- FINDINGS-prom_a-ring-buffers.md
;           has the capacities, not the traffic
; Was `sub_FE1D29`, named by notes/prom_a_census_round8.py (bucket T1).
; ---------------------------------------------------------------------
Ring_InitTenOfFourteen:
	call T_TimedEventRing_Init                               ; FE1D29  1d 70 1d f4
	call T_SeqBufRing_Init                               ; FE1D2D  1d 94 1d f4
	call T_MidiInARing_Init                               ; FE1D31  1d b8 1d f4
	call T_MidiInBRing_Init                               ; FE1D35  1d dc 1d f4
	call T_Ring601432_Init                               ; FE1D39  1d 00 1e f4
	call T_Ring60153C_Init                               ; FE1D3D  1d 24 1e f4
	call T_Ring601646_Init                               ; FE1D41  1d 48 1e f4
	call T_Ring601850_Init                               ; FE1D45  1d 6c 1e f4
	call T_Ring60195A_Init                               ; FE1D49  1d 28 1d f4
	call T_Ring601C6E_Init                               ; FE1D4D  1d b4 1e f4
	ret                                                  ; FE1D51  0e
