	add XBC,0x007e0000                                   ; FE4C8D  e9 c8 00 00 7e 00
	ld A,(XSP+0x08)                                      ; FE4C93  8f 08 21
	ld (XBC),A                                           ; FE4C96  b1 41
	ret                                                  ; FE4C98  0e
