	cp wa, 0x00:i3                                  ; FE5D0C  d8 d8
	jr lt, .LFE5D2D                               ; FE5D0E  61 1d
	cp wa, 0x06:i3                                  ; FE5D10  d8 de
	jr gt, .LFE5D2D                               ; FE5D12  6a 19
