Fdc_ValidateJumpTable:
; index = the request's operation word.  Base 0xFE5746.
	.short 0x0000                                  ; FE6E46   0 -> 0xFE5746  geometry setup
	.short 0x0009                                  ; FE6E48   1 -> 0xFE574F  generic check
	.short 0x0009                                  ; FE6E4A   2 -> 0xFE574F
