	sub XBC,XBC                                          ; FE75E7  e9 a1
	inc 1,XBC                                            ; FE75E9  e9 61
	add (xiz-4), xbc                                     ; FE75EB  ae fc 89
	add XIX,XBC                                          ; FE75EE  e9 84
	add HL,BC                                            ; FE75F0  d9 83
	cp HL,0x0020                                         ; FE75F2  db cf 20 00
	jr lt, .LFE75E0                                           ; FE75F6  61 e8
	jr .LFE7601                                              ; FE75F8  68 07
.LFE75FA:
	ld (XIX),0x00                                        ; FE75FA  b4 00 00
