; ---------------------------------------------------------------------
; BootSector_Floppy720K -- 32 bytes: the head of a DOS FAT12 boot sector
;
; Copied to RAM 0x60A080 by DiskImage_Build720K, which then zero-fills to 512.
;
;   +0x00  EB 1C 90        x86 JMP SHORT +0x1C / NOP
;   +0x03  "Technics"      OEM name  ★ the machine signs its own disks
;   +0x0B  512             bytes per sector
;   +0x0D  2               sectors per cluster
;   +0x0E  1               reserved sectors
;   +0x10  2               number of FATs
;   +0x11  112             root directory entries
;   +0x13  1440            total sectors
;   +0x15  0xF9            media descriptor -- 3.5" 720 KB, double density
;   +0x16  3               sectors per FAT
;   +0x18  9               sectors per track
;   +0x1A  2               heads
;   +0x1C  0               hidden sectors (16-bit form)
;   +0x1E  EB FE           x86 JMP $ -- an unbootable one-instruction stub
;
; ★ ARITHMETIC CHECK: 1440 = 80 x 2 x 9 exactly, and 1440 x 512 = 737,280 =
;   720 KiB.  The media byte 0xF9 is the IBM value for that geometry, and
;   Disk_Format720K's verify read asks for sector 9 of track 79 -- the last
;   sector this BPB describes.  Four statements, one geometry.
; ---------------------------------------------------------------------
BootSector_Floppy720K:
	.byte 0xeb, 0x1c, 0x90, 0x54, 0x65, 0x63, 0x68, 0x6e, 0x69, 0x63, 0x73, 0x00, 0x02, 0x02, 0x01, 0x00  ; FE76B2
	.byte 0x02, 0x70, 0x00, 0xa0, 0x05, 0xf9, 0x03, 0x00, 0x09, 0x00, 0x02, 0x00, 0x00, 0x00, 0xeb, 0xfe  ; FE76C2
; ---------------------------------------------------------------------
; FatId_Floppy720K -- 32 bytes: F9 FF FF, then 29 zero bytes
;
; Copied to the start of the FAT area by DiskImage_Build720K, which zero-fills
; the rest.  F9 FF FF is the FAT12 identifier triple for media descriptor 0xF9:
; entry 0 = media byte with the top nibble set, entry 1 = end-of-chain.  It
; matches BootSector_Floppy720K's +0x15 byte exactly, which is the check.
; ---------------------------------------------------------------------
FatId_Floppy720K:
	.byte 0xf9, 0xff, 0xff, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00  ; FE76D2
	.byte 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00  ; FE76E2
; ---------------------------------------------------------------------
; BootSector_Floppy1440K -- 32 bytes: the head of a DOS FAT12 boot sector
;
; Copied to RAM 0x60A080 by DiskImage_Build1440K.  Identical in layout to
; BootSector_Floppy720K, and it differs in exactly six fields:
;
;   +0x0D  1               sectors per cluster   (was 2)
;   +0x11  224             root directory entries (was 112)
;   +0x13  2880            total sectors          (was 1440)
;   +0x15  0xF0            media descriptor -- 3.5" 1.44 MB, high density
;   +0x16  9               sectors per FAT        (was 3)
;   +0x18  18              sectors per track      (was 9)
;
; ★ ARITHMETIC CHECK: 2880 = 80 x 2 x 18 exactly, 2880 x 512 = 1,474,560 =
;   1.44 MB in the marketing sense, and Disk_Format1440K's verify read asks for
;   sector 18 of track 79.  The OEM name is again "Technics".
; ---------------------------------------------------------------------
BootSector_Floppy1440K:
	.byte 0xeb, 0x1c, 0x90, 0x54, 0x65, 0x63, 0x68, 0x6e, 0x69, 0x63, 0x73, 0x00, 0x02, 0x01, 0x01, 0x00  ; FE76F2
	.byte 0x02, 0xe0, 0x00, 0x40, 0x0b, 0xf0, 0x09, 0x00, 0x12, 0x00, 0x02, 0x00, 0x00, 0x00, 0xeb, 0xfe  ; FE7702
; ---------------------------------------------------------------------
; FatId_Floppy1440K -- 32 bytes: F0 FF FF, then 29 zero bytes
;
; The FAT12 identifier triple for media descriptor 0xF0, matching
; BootSector_Floppy1440K's +0x15 byte.  Copied by DiskImage_Build1440K.
; ---------------------------------------------------------------------
FatId_Floppy1440K:
	.byte 0xf0, 0xff, 0xff, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00  ; FE7712
	.byte 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00  ; FE7722
	ret                                                  ; FE7732  0e

; 0xFE7733-0xFE77FF -- 205 bytes of 0x0E (RET), module padding.
; Checked byte by byte, not sampled: notes/gen_prom_a_block.py refuses to
; emit this directive unless set(ROM[lo:hi]) == {0x0E}.
	.fill 205, 1, 0x0E

