	lda xbc, (DL_F583AB:24)                              ; FF558F  f2 ab 83 f5 31
	push XBC                                             ; FF5594  39
	lda xwa, (DL_FloppyDisk:24)                          ; FF5595  f2 88 82 f5 30
	push XWA                                             ; FF559A  38
	call DisplayList_RunOnLayer_SaveRegs                                      ; FF559B  1d d3 75 ff
